BEGIN;

-- Ficha de Vicente García.
--
-- La biografía de relleno no daba un solo hecho verificable: ni Calor Urbano, ni Melodrama, ni
-- A la Mar, ni Candela, ni un solo premio. occupations: composer, guitarist, producer (agrega
-- producer; ya coproductor desde A la Mar). Premios registrados solo con ≥2 fuentes
-- independientes; Concierto del Año 2023 (Soberano) y Compositor del Año 2026 (Soberano) no se
-- registran por conflicto o falta de segunda fuente: ver CONFLICTOS_DE_DATO.md.

UPDATE artists SET occupations = '["composer","guitarist","producer"]'::jsonb WHERE slug = 'vicente-garcia';

INSERT INTO award_categories (award_id, name)
SELECT a.id, 'Best New Artist' FROM awards a WHERE a.name = 'Latin Grammy'
   AND NOT EXISTS (SELECT 1 FROM award_categories c WHERE c.award_id = a.id AND c.name = 'Best New Artist');

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2017, NULL, true, 'Grammy.com (17 nov 2017); Latino USA (29 dic 2017)'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'vicente-garcia' AND a.name = 'Latin Grammy' AND cat.name = 'Best New Artist'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2017);

INSERT INTO award_categories (award_id, name)
SELECT a.id, 'Best Singer-Songwriter Album' FROM awards a WHERE a.name = 'Latin Grammy'
   AND NOT EXISTS (SELECT 1 FROM award_categories c WHERE c.award_id = a.id AND c.name = 'Best Singer-Songwriter Album');

